// Shortest augmenting path Hungarian algorithm (O(n^3)).
// cost: n x n row-major double array.
// assignment: output array of length n, assignment[i] = column assigned to row i.
void hungarian(const double* cost, int n, int64_t* assignment) {
    const double INF = 1e300;
    double* u = (double*)calloc(n+1, sizeof(double));
    double* v = (double*)calloc(n+1, sizeof(double));
    int64_t* p = (int64_t*)calloc(n+1, sizeof(int64_t));
    int64_t* way = (int64_t*)calloc(n+1, sizeof(int64_t));
    double* minv = (double*)malloc((n+1)*sizeof(double));
    unsigned char* used = (unsigned char*)calloc(n+1, sizeof(unsigned char));

    for (int i = 1; i <= n; i++) {
        p[0] = i;
        int j0 = 0;
        for (int j = 0; j <= n; j++) { minv[j] = INF; used[j] = 0; }
        while (1) {
            used[j0] = 1;
            int i0 = p[j0];
            double delta = INF;
            int j1 = -1;
            const double* row = cost + (i0-1)*n;
            double ui = u[i0];
            for (int j = 1; j <= n; j++) {
                if (!used[j]) {
                    double cur = row[j-1] - ui - v[j];
                    if (cur < minv[j]) {
                        minv[j] = cur;
                        way[j] = j0;
                    }
                    if (minv[j] < delta) {
                        delta = minv[j];
                        j1 = j;
                    }
                }
            }
            for (int j = 0; j <= n; j++) {
                if (used[j]) {
                    u[p[j]] += delta;
                    v[j] -= delta;
                } else {
                    minv[j] -= delta;
                }
            }
            j0 = j1;
            if (p[j0] == 0) break;
        }
        while (1) {
            int j1 = way[j0];
            p[j0] = p[j1];
            j0 = j1;
            if (j0 == 0) break;
        }
    }
    for (int j = 1; j <= n; j++) {
        assignment[p[j]-1] = j-1;
    }
    free(u); free(v); free(p); free(way); free(minv); free(used);
}
