extern void gcm_ghash_clmul(u64 Xi[2], const u128 Htable[16], const uint8_t *inp, size_t len);
extern void gcm_gmult_clmul(u64 Xi[2], const u128 Htable[16]);
extern void aesni_ctr32_encrypt_blocks(const uint8_t *in, uint8_t *out, size_t blocks, const AES_KEY *key, const uint8_t ivec[16]);

#define NTHREADS 6

typedef struct {
    const uint8_t *in;
    uint8_t *out;
    size_t blocks;
    AES_KEY *key;
    uint8_t ivec[16];
} ctr_job;

static void *ctr_worker(void *arg) {
    ctr_job *j = (ctr_job*)arg;
    aesni_ctr32_encrypt_blocks(j->in, j->out, j->blocks, j->key, j->ivec);
    return NULL;
}

// Encrypt plaintext (len bytes, multiple of 16) with AES-GCM.
// Returns ciphertext (malloc) and tag (16 bytes).
void fast_gcm(const uint8_t *key, int key_bits, const uint8_t *nonce, size_t nonce_len,
              const uint8_t *pt, size_t pt_len, const uint8_t *aad, size_t aad_len,
              uint8_t *ct, uint8_t *tag) {
    AES_KEY aes_key;
    AES_set_encrypt_key(key, key_bits, &aes_key);

    // H = E_K(0^128)
    uint8_t zero[16] = {0};
    uint8_t H[16];
    AES_encrypt(zero, H, &aes_key);

    // J0 = nonce || 0^31 || 1  (for 12-byte nonce)
    uint8_t J0[16];
    memcpy(J0, nonce, nonce_len);
    memset(J0 + nonce_len, 0, 16 - nonce_len);
    J0[15] = 0x01;

    // S = E_K(J0)
    uint8_t S[16];
    AES_encrypt(J0, S, &aes_key);

    // Parallel CTR: counter starts at inc32(J0) = nonce || 0x00000002
    size_t total_blocks = pt_len / 16;
    pthread_t threads[NTHREADS];
    ctr_job jobs[NTHREADS];
    size_t blocks_per = total_blocks / NTHREADS;
    size_t rem = total_blocks % NTHREADS;
    size_t start = 0;
    for (int i = 0; i < NTHREADS; i++) {
        size_t nb = blocks_per + (i < (int)rem ? 1 : 0);
        jobs[i].in = pt + start * 16;
        jobs[i].out = ct + start * 16;
        jobs[i].blocks = nb;
        jobs[i].key = &aes_key;
        memcpy(jobs[i].ivec, nonce, nonce_len);
        memset(jobs[i].ivec + nonce_len, 0, 16 - nonce_len);
        uint32_t ctr = 2 + (uint32_t)start;
        jobs[i].ivec[12] = (ctr >> 24) & 0xff;
        jobs[i].ivec[13] = (ctr >> 16) & 0xff;
        jobs[i].ivec[14] = (ctr >> 8) & 0xff;
        jobs[i].ivec[15] = ctr & 0xff;
        if (nb > 0) pthread_create(&threads[i], NULL, ctr_worker, &jobs[i]);
        start += nb;
    }
    for (int i = 0; i < NTHREADS; i++) {
        if (jobs[i].blocks > 0) pthread_join(threads[i], NULL);
    }

    // GHASH
    u128 Htable[16];
    u64 Xi[2] = {0, 0};
    // H as u64[2]: need correct byte order. gcm_init_clmul expects Xi[2] = H in u64 form.
    // H is 16 bytes big-endian. Xi[0] = low 64 bits, Xi[1] = high 64 bits.
    u64 Hlow = 0, Hhigh = 0;
    for (int i = 0; i < 8; i++) {
        Hhigh = (Hhigh << 8) | H[i];
        Hlow = (Hlow << 8) | H[8 + i];
    }
    u64 Harr[2] = {Hlow, Hhigh};
    gcm_init_clmul(Htable, Harr);

    if (aad_len > 0) {
        gcm_ghash_clmul(Xi, Htable, aad, aad_len);
    }
    gcm_ghash_clmul(Xi, Htable, ct, pt_len);

    // length block: aad_len*8 (64-bit BE) || pt_len*8 (64-bit BE)
    uint8_t lenblock[16];
    uint64_t aad_bits = (uint64_t)aad_len * 8;
    uint64_t ct_bits = (uint64_t)pt_len * 8;
    for (int i = 0; i < 8; i++) {
        lenblock[i] = (aad_bits >> (56 - 8*i)) & 0xff;
        lenblock[8+i] = (ct_bits >> (56 - 8*i)) & 0xff;
    }
    gcm_ghash_clmul(Xi, Htable, lenblock, 16);

    // tag = Xi XOR S. Xi is u64[2] = {low, high}. Need 16 bytes big-endian.
    uint8_t xibytes[16];
    for (int i = 0; i < 8; i++) {
        xibytes[i] = (Xi[1] >> (56 - 8*i)) & 0xff;      // high 64 bits first
        xibytes[8+i] = (Xi[0] >> (56 - 8*i)) & 0xff;    // low 64 bits
    }
    for (int i = 0; i < 16; i++) tag[i] = xibytes[i] ^ S[i];
}

int main() {
    // test with random data
    srand(42);
    uint8_t key[16], nonce[12];
    for (int i = 0; i < 16; i++) key[i] = rand();
    for (int i = 0; i < 12; i++) nonce[i] = rand();
    size_t pt_len = 61440000;
    uint8_t *pt = malloc(pt_len);
    uint8_t *ct = malloc(pt_len);
    uint8_t tag[16];
    for (size_t i = 0; i < pt_len; i++) pt[i] = rand();
    uint8_t aad[32];
    for (int i = 0; i < 32; i++) aad[i] = rand();

    // warmup
    fast_gcm(key, 128, nonce, 12, pt, pt_len, aad, 32, ct, tag);

    struct timespec t0, t1;
    clock_gettime(CLOCK_MONOTONIC, &t0);
    int iters = 20;
    for (int i = 0; i < iters; i++) {
        fast_gcm(key, 128, nonce, 12, pt, pt_len, aad, 32, ct, tag);
    }
    clock_gettime(CLOCK_MONOTONIC, &t1);
    double ms = ((t1.tv_sec - t0.tv_sec) * 1e3 + (t1.tv_nsec - t0.tv_nsec) / 1e6) / iters;
    printf("fast_gcm: %.3f ms\n", ms);

    // print first bytes of ct and tag for verification
    printf("ct[0..3] = %02x %02x %02x %02x\n", ct[0], ct[1], ct[2], ct[3]);
    printf("tag = ");
    for (int i = 0; i < 16; i++) printf("%02x", tag[i]);
    printf("\n");
    return 0;
}
EOF
