    //   X = X * H^chunk_blocks  (for i>0; for i=0, X_aad already needs *H^chunk_blocks? no)
    //   X = X XOR X_i
    // Wait let's derive sequential:
    // X = X_aad * H^{total_blocks} XOR X_0 * H^{suffix_0} XOR X_1 * H^{suffix_1} ... XOR X_{n-1}
    // suffix_0 = total_blocks - len_0, suffix_1 = total_blocks - len_0 - len_1, etc.
    // Sequential combine from X_aad:
    //   acc = X_aad
    //   for i in 0..n-1:
    //       acc = acc * H^{len_i} XOR X_i
    //   This gives: X_aad * H^{len_0} * H^{len_1} ... = X_aad * H^{total_blocks}, then XOR X_0 * H^{len_1+...}, etc. Correct!
    // So: acc = X_aad; for each chunk i: acc = acc * H^{len_i} XOR X_i.
    // len_i in blocks = chunk_blocks (same for all if divisible).
    // acc * H^{len_i} = gf_mul(acc, H^len_i). We have Hchunk = H^chunk_blocks.
    // So per chunk: acc = gf_mul(acc, Hchunk) XOR X_i. Cheap (6 gf_muls).

    u64 acc[2] = {Xi[0], Xi[1]};
    for (int i = 0; i < NTHREADS; i++) {
        gf_mul(acc, Hchunk);
        acc[0] ^= ghjobs[i].Xi[0];
        acc[1] ^= ghjobs[i].Xi[1];
    }

    // length block
    uint8_t lenblock[16];
    uint64_t aad_bits = (uint64_t)aad_len * 8;
    uint64_t ct_bits = (uint64_t)pt_len * 8;
    for (int i = 0; i < 8; i++) {
        lenblock[i] = (aad_bits >> (56 - 8*i)) & 0xff;
        lenblock[8+i] = (ct_bits >> (56 - 8*i)) & 0xff;
    }
    gcm_ghash_clmul(acc, Htable, lenblock, 16);

    // S = E_K(J0)
    uint8_t J0[16];
    memcpy(J0, nonce, nonce_len);
    memset(J0 + nonce_len, 0, 16 - nonce_len);
    J0[15] = 0x01;
    uint8_t S[16];
    AES_encrypt(J0, S, &aes_key);

    uint8_t xibytes[16];
    for (int i = 0; i < 8; i++) {
        xibytes[i] = (acc[0] >> (8*i)) & 0xff;
        xibytes[8+i] = (acc[1] >> (8*i)) & 0xff;
    }
    for (int i = 0; i < 16; i++) tag[i] = xibytes[i] ^ S[i];
}

int main() {
    srand(42);
    uint8_t key[16], nonce[12];
    for (int i = 0; i < 16; i++) key[i] = rand();
    for (int i = 0; i < 12; i++) nonce[i] = rand();
    size_t pt_len = 61440000;
    uint8_t *pt = malloc(pt_len);
    uint8_t *ct = malloc(pt_len);
    uint8_t tag[16];
    for (size_t i = 0; i < pt_len; i++) pt[i] = rand();
    uint8_t aad[32];
    for (int i = 0; i < 32; i++) aad[i] = rand();

    fast_gcm(key, 128, nonce, 12, pt, pt_len, aad, 32, ct, tag);

    struct timespec t0, t1;
    clock_gettime(CLOCK_MONOTONIC, &t0);
    int iters = 20;
    for (int i = 0; i < iters; i++) {
        fast_gcm(key, 128, nonce, 12, pt, pt_len, aad, 32, ct, tag);
    }
    clock_gettime(CLOCK_MONOTONIC, &t1);
    double ms = ((t1.tv_sec - t0.tv_sec) * 1e3 + (t1.tv_nsec - t0.tv_nsec) / 1e6) / iters;
    printf("fast_gcm2: %.3f ms\n", ms);

    printf("ct[0..3] = %02x %02x %02x %02x\n", ct[0], ct[1], ct[2], ct[3]);
    printf("tag = ");
    for (int i = 0; i < 16; i++) printf("%02x", tag[i]);
    printf("\n");
    return 0;
}
EOF
export TMPDIR=$(pwd); gcc -O3 -march=native -o fastgcm2 fastgcm2.c -L/usr/local/lib -lcrypto -lpthread -I/usr/local/include 2>&1 | grep -v "deprecated\|note:\|expanded\|OSSL_DEPRECATED\|^ *[0-9]* |\|^ *\^" | head; ./fastgcm2"}

