{"command":"cd "$(pwd)" && python3 - << 'EOF'
src = open('fastgcm2.c').read()
old = '''static void gf_mul(u64 Xi[2], const u64 v[2]) {
    u128 vtable[16];
    gcm_init_clmul(vtable, v);
    uint8_t zero[16] = {0};
    gcm_ghash_clmul(Xi, vtable, zero, 16);
}'''
new = '''static void gf_mul(u64 Xi[2], const u64 v[2]) {
    // multiply Xi by v in GF(2^128). v is given as {high, low} (byte-reversed u64).
    // Build the byte representation of v and use gcm_ghash_clmul with a single block.
    uint8_t vb[16];
    for (int i = 0; i < 8; i++) {
        vb[i] = (v[0] >> (8*i)) & 0xff;
        vb[8+i] = (v[1] >> (8*i)) & 0xff;
    }
    u128 vtable[16];
    gcm_init_clmul(vtable, v);
    gcm_ghash_clmul(Xi, vtable, vb, 16);
}'''
assert old in src
open('fastgcm2.c','w').write(src.replace(old, new))
print('patched')
